//! The zoo goldens (`tests/goldens/zoo.json`, generated by `cargo xtask cli-goldens` with a real CPython 3.13.14
//! argparse built from `export_json` of `tests/zoo/spec.rs`), replayed through snp-argparse: help, version and usage
//! errors byte for byte, successful parses value for value.
//!
//! Owner: WP-12.

#[cfg(test)]
#[path = "zoo/spec.rs"]
mod spec;

#[cfg(test)]
mod zoo {
    use std::ffi::OsString;

    use serde_json::Value;
    use snp_argparse::{Namespace, Outcome, ParseCfg};
    use snp_core::env::Env;

    use crate::spec::ZOO;

    fn os(v: &Value) -> OsString {
        OsString::from(v.as_str().unwrap())
    }

    fn chain(ns: &Namespace) -> Vec<&Namespace> {
        let mut out = vec![ns];
        let mut cur = ns;
        while let Some((_, sub)) = cur.command() {
            out.push(sub);
            cur = sub;
        }
        out
    }

    fn check_ns(id: &str, ns: &Namespace, expected: &serde_json::Map<String, Value>) {
        let levels = chain(ns);
        for (key, want) in expected {
            match want {
                Value::Null => {
                    for l in &levels {
                        assert!(
                            l.value(key).is_none()
                                && l.int(key).is_none()
                                && l.list(key).is_empty(),
                            "{id}: {key} should be None"
                        );
                    }
                }
                Value::Bool(b) => {
                    let got = levels.iter().any(|l| l.flag(key));
                    assert_eq!(got, *b, "{id}: {key}");
                }
                Value::Number(n) => {
                    let got = levels.iter().rev().find_map(|l| l.int(key));
                    assert_eq!(got, n.as_i64(), "{id}: {key}");
                }
                Value::String(s) => {
                    let got = levels.iter().rev().find_map(|l| l.value(key));
                    assert_eq!(
                        got.and_then(|g| g.to_str()),
                        Some(s.as_str()),
                        "{id}: {key}"
                    );
                }
                Value::Array(items) => {
                    let want: Vec<OsString> = items.iter().map(os).collect();
                    let got = levels
                        .iter()
                        .rev()
                        .map(|l| l.list(key))
                        .find(|l| !l.is_empty())
                        .unwrap_or_default();
                    assert_eq!(got, want.as_slice(), "{id}: {key}");
                }
                Value::Object(_) => panic!("{id}: unexpected {want:?}"),
            }
        }
    }

    #[test]
    fn zoo_matches_cpython_argparse() {
        let text = std::fs::read_to_string(
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/goldens/zoo.json"),
        )
        .unwrap();
        let doc: Value = serde_json::from_str(&text).unwrap();
        let cases = doc["cases"].as_array().unwrap();
        assert!(cases.len() > 100, "{} cases", cases.len());
        let mut failures = Vec::new();
        for case in cases {
            let id = case["id"].as_str().unwrap();
            let name = case["spec"].as_str().unwrap();
            let spec = ZOO.iter().find(|(n, _)| *n == name).unwrap().1;
            let argv: Vec<OsString> = case["argv"].as_array().unwrap().iter().map(os).collect();
            let env = Env::from_pairs(
                case["env"]
                    .as_object()
                    .unwrap()
                    .iter()
                    .map(|(k, v)| (OsString::from(k), os(v))),
            );
            let cfg = ParseCfg {
                prog: case["prog"].as_str().unwrap(),
                env: &env,
                columns: snp_argparse::columns(&env, None),
            };
            let exit = case["exit"].as_i64().unwrap();
            let stdout = case["stdout"].as_str().unwrap();
            let stderr = case["stderr"].as_str().unwrap();
            let got = snp_argparse::parse(spec, &argv, &cfg);
            let ok = match (&got, case["ns"].as_object()) {
                (Outcome::Parsed(ns), Some(want)) => {
                    match std::panic::catch_unwind(|| check_ns(id, ns, want)) {
                        Ok(()) => true,
                        Err(e) => {
                            failures.push(format!("{id}: {e:?}"));
                            continue;
                        }
                    }
                }
                (Outcome::Help(s) | Outcome::Version(s), None) => exit == 0 && s == stdout,
                (Outcome::Usage { stderr: s }, None) => exit == 2 && s == stderr,
                _ => false,
            };
            if !ok {
                failures.push(format!(
                    "{id}: expected exit {exit}\n--- stdout\n{stdout}--- stderr\n{stderr}--- got\n{got:#?}"
                ));
            }
        }
        assert!(
            failures.is_empty(),
            "{} of {} cases differ:\n{}",
            failures.len(),
            cases.len(),
            failures.join("\n")
        );
    }

    #[test]
    fn zoo_specs_round_trip_through_export_json() {
        for (name, spec) in &ZOO {
            let json = snp_argparse::export_json(spec, name);
            let v: Value = serde_json::from_str(&json).unwrap();
            assert_eq!(v["prog"], Value::String((*name).to_owned()));
            assert!(v["parser"]["actions"].is_array());
        }
    }
}
